// ============================================================================
//  SABIDURÍAS DEL MUNDO: lugares, ciudadanos, encargos, anécdotas y libros
//  Todas las plazas de esta ruta usan la misma distribución (3 pensadores + maestro).
// ============================================================================
const P5 = [[15, 24], [-16, 30], [6, -40], [-15, -24], [16, -24]];
const N3 = [{ at: [-6, 26], path: [6, 0] }, { at: [17, -10], path: [0, -6] }, { at: [-6, -22], path: [-6, 0] }];
const B2 = [[14, 12], [-15, 4]];
const wpoi = (i, id, name, text, fact, q) => ({ id, at: P5[i], name, text, fact, q });
const wnpc = (i, id, name, role, lookObj, lines, female) => ({ id, name, role, female: !!female, ...N3[i], look: lookObj, lines });

POIS.push(
  [ // X · Mexicas
    wpoi(0, 'templomayor', 'El Templo Mayor', 'En el centro de Tenochtitlan se alzaba el Templo Mayor, una pirámide con dos santuarios en lo alto: uno para Tláloc, dios de la lluvia, pintado de azul, y otro para Huitzilopochtli, dios del Sol y de la guerra, pintado de rojo. Representaba la montaña sagrada.', 'Sus ruinas se redescubrieron en 1978, cuando unos trabajadores de la compañía de luz encontraron un enorme monolito de la diosa lunar Coyolxauhqui.',
      { q: '¿A qué dos dioses estaba dedicado el Templo Mayor?', a: ['Tláloc y Huitzilopochtli', 'Quetzalcóatl y Tezcatlipoca', 'Inti y Viracocha', 'Zeus y Apolo'], e: 'La lluvia y la agricultura, el Sol y la guerra.' }),
    wpoi(1, 'calmecac', 'Las escuelas mexicas', 'Los mexicas tenían educación obligatoria para todos los jóvenes, chicos y chicas, algo excepcional en el mundo del siglo quince. En el telpochcalli aprendían oficios y el arte de la guerra; en el calmécac, los cantos, el calendario, la historia y el arte de hablar bien.', 'Los maestros insistían en el arte de la palabra: hablar con elegancia era una señal de sabiduría y de buen corazón.',
      { q: '¿Qué tenía de excepcional la educación mexica?', a: ['Era obligatoria para todos los jóvenes, chicos y chicas', 'Solo era para los reyes', 'Se hacía en latín', 'No existía'], e: 'En el telpochcalli y en el calmécac.' }),
    wpoi(2, 'piedrasol', 'La Piedra del Sol', 'La Piedra del Sol es un enorme disco de basalto de casi cuatro metros y unas veinticuatro toneladas. En el centro aparece un rostro, y a su alrededor los símbolos de las cuatro eras anteriores, los veinte días del calendario y los rayos del Sol.', 'Estuvo enterrada en el Zócalo de la Ciudad de México hasta 1790. Hoy está en el Museo Nacional de Antropología.',
      { q: '¿Qué representa la Piedra del Sol?', a: ['Las eras del mundo y el calendario mexica', 'Un mapa de Tenochtitlan', 'Un juego de pelota', 'La conquista española'], e: 'El Quinto Sol y los cuatro anteriores.' }),
    wpoi(3, 'chinampas', 'Las chinampas', 'Para cultivar sobre el lago, los mexicas construyeron chinampas: huertos de lodo y raíces rodeados de canales, sujetos con ahuejotes, unos árboles altos y delgados. Daban varias cosechas al año de maíz, frijol, calabaza, chile y flores.', 'En Xochimilco todavía se cultivan chinampas, y desde 1987 son Patrimonio de la Humanidad.',
      { q: '¿Qué eran las chinampas?', a: ['Huertos construidos sobre el lago entre canales', 'Templos en lo alto de las montañas', 'Barcos de guerra', 'Escuelas para nobles'], e: 'Un sistema agrícola muy productivo.' }),
    wpoi(4, 'tlatelolco', 'El mercado de Tlatelolco', 'En Tlatelolco, ciudad hermana de Tenochtitlan, estaba el mayor mercado de América. Los conquistadores se asombraron: decenas de miles de personas compraban y vendían cacao, mantas, plumas, oro, jade, alimentos y medicinas, con jueces que vigilaban que las medidas fueran justas.', 'Se usaban granos de cacao como moneda. Incluso había falsificadores que vaciaban los granos y los rellenaban de tierra.',
      { q: '¿Qué usaban los mexicas como moneda en el mercado?', a: ['Granos de cacao', 'Monedas de plata', 'Conchas de ostra', 'Billetes de papel'], e: 'También mantas de algodón para valores mayores.' }),
  ],
  [ // XI · Incas
    wpoi(0, 'cusco', 'Cusco y el Coricancha', 'Cusco, la capital inca, tenía forma de puma según la tradición. En su centro estaba el Coricancha, el templo del Sol, con muros cubiertos de láminas de oro y un jardín con plantas y animales de oro y plata.', 'Los muros incas de piedra encajada resistieron terremotos que derribaron muchos edificios coloniales construidos encima.',
      { q: '¿A qué dios estaba dedicado el Coricancha?', a: ['A Inti, el Sol', 'A Huitzilopochtli', 'A la Luna solamente', 'A Viracocha solo'], e: 'Coricancha significa recinto de oro.' }),
    wpoi(1, 'qhapaqnan', 'El Qhapaq Ñan', 'Los incas construyeron una red de caminos de unos treinta mil kilómetros, del sur de Colombia al centro de Chile y Argentina. Cruzaban desiertos, selvas y montañas de más de cinco mil metros, con puentes colgantes de fibra vegetal y tambos para descansar.', 'El puente de Q’eswachaka, de cuerdas de hierba, se renueva cada año en una minka de varias comunidades, como hace siglos.',
      { q: '¿Cómo se llama la red de caminos de los incas?', a: ['Qhapaq Ñan', 'Ruta de la Seda', 'Vía Apia', 'Camino Real de Tierra Adentro'], e: 'Hoy es Patrimonio de la Humanidad.' }),
    wpoi(2, 'sacsayhuaman', 'Sacsayhuamán', 'Sobre Cusco se levanta Sacsayhuamán, un enorme recinto de muros en zigzag con piedras de más de cien toneladas, encajadas con tal precisión que no cabe entre ellas ni una hoja. Hoy se celebra allí el Inti Raymi, la fiesta del Sol, cada 24 de junio.', 'Nadie sabe con certeza cómo movieron y tallaron piedras tan grandes sin ruedas ni animales de tiro poderosos.',
      { q: '¿Qué fiesta se celebra hoy en Sacsayhuamán cada 24 de junio?', a: ['El Inti Raymi, fiesta del Sol', 'El We Tripantu', 'El Día de Muertos', 'El Año Nuevo chino'], e: 'Coincide con el solsticio de invierno andino.' }),
    wpoi(3, 'moray', 'Andenes y Moray', 'Los incas cultivaban las montañas con andenes, terrazas escalonadas que evitan la erosión y aprovechan el agua. En Moray construyeron círculos concéntricos de terrazas con distintas temperaturas: quizá un laboratorio para adaptar cultivos.', 'Los andinos domesticaron miles de variedades de papa y la conservaban congelándola y secándola: el chuño.',
      { q: '¿Para qué servían los andenes incas?', a: ['Para cultivar en las montañas sin erosión', 'Para correr carreras', 'Para guardar tesoros', 'Para observar estrellas'], e: 'Todavía se usan muchos.' }),
    wpoi(4, 'quipus', 'Los quipus', 'Los quipus eran cordeles de algodón o lana con nudos de distintos tipos y colores. Los quipucamayoc registraban en ellos censos, cosechas y tributos usando un sistema decimal. Quizá también guardaban relatos y genealogías.', 'Hoy se conservan unos mil cuatrocientos quipus en museos. Investigadores de todo el mundo siguen intentando descifrar los que no son solo números.',
      { q: '¿Qué sistema numérico usaban los quipus?', a: ['Decimal', 'Binario', 'Romano', 'Ninguno'], e: 'La posición del nudo indicaba unidades, decenas, centenas...' }),
  ],
  [ // XII · Mapuche
    wpoi(0, 'ruka', 'La ruka', 'La ruka es la casa tradicional mapuche, de madera y paja, con la puerta mirando al oriente, por donde sale el sol. En el centro arde el fogón, el kütral, alrededor del cual se conversa, se come y se transmiten los saberes.', 'El humo del fogón sale por la paja del techo y ayuda a conservar la casa y los alimentos colgados.',
      { q: '¿Hacia dónde suele mirar la puerta de la ruka?', a: ['Hacia el oriente, por donde sale el sol', 'Hacia el mar', 'Hacia el sur', 'No importa'], e: 'El este es la dirección más sagrada.' }),
    wpoi(1, 'rewe', 'El rewe y el Ngillatun', 'El rewe es un tronco tallado con escalones, plantado junto a la casa de la machi. Es la escalera que une los mundos. En el Ngillatun, la gran rogativa, varias comunidades se reúnen durante días alrededor del rewe para agradecer y pedir por el equilibrio.', 'En el Ngillatun se baila el purrun alrededor del espacio ceremonial, al son del kultrún y la trutruka.',
      { q: '¿Qué es el Ngillatun?', a: ['Una gran ceremonia comunitaria de agradecimiento', 'Un juego de pelota', 'Un tipo de casa', 'Una guerra'], e: 'Reúne a varias comunidades.' }),
    wpoi(2, 'pewen', 'Las araucarias', 'La araucaria, pewen en mapudungun, es un árbol que puede vivir más de mil años en las laderas de los volcanes. Sus semillas, los piñones, son el alimento sagrado de los pewenche, la gente del pewen, que los recogen en otoño.', 'Las araucarias existen desde la época de los dinosaurios. Son verdaderos fósiles vivientes.',
      { q: '¿Qué alimento dan las araucarias?', a: ['Piñones', 'Manzanas', 'Maíz', 'Papas'], e: 'Se comen cocidos, tostados o en harina.' }),
    wpoi(3, 'wetripantu', 'El We Tripantu', 'El We Tripantu es el año nuevo mapuche. Se celebra en el solsticio de invierno, hacia el 24 de junio, cuando el sol empieza a volver y los días se alargan. Las familias se reúnen la noche anterior y al amanecer se bañan en el río para renovarse.', 'Desde 2021, en Chile el día del solsticio de invierno es feriado nacional en honor a los pueblos originarios.',
      { q: '¿Cuándo se celebra el We Tripantu?', a: ['En el solsticio de invierno, hacia el 24 de junio', 'El 1 de enero', 'En el equinoccio de primavera', 'El 12 de octubre'], e: 'Significa «nueva salida del sol».' }),
    wpoi(4, 'quilin', 'El Parlamento de Quilín', 'En 1641, autoridades españolas y lonkos mapuches se reunieron en Quilín. Tras días de discursos y ceremonias, acordaron una frontera en el río Biobío: al sur, el territorio mapuche sería independiente. Fue uno de los primeros tratados entre un imperio europeo y un pueblo originario de América.', 'Los parlamentos se repitieron durante dos siglos. Eran grandes encuentros diplomáticos con miles de asistentes.',
      { q: '¿Qué río fijó como frontera el Parlamento de Quilín?', a: ['El Biobío', 'El Maule', 'El Amazonas', 'El Paraná'], e: 'Al sur quedó el territorio mapuche.' }),
  ],
  [ // XIII · China
    wpoi(0, 'muralla', 'La Gran Muralla', 'La Gran Muralla no es un solo muro, sino muchas murallas construidas durante dos mil años para proteger a China de los pueblos del norte. El primer emperador, Qin Shi Huang, unió los primeros tramos; la que más se visita hoy es de la dinastía Ming.', 'No es cierto que se vea a simple vista desde la Luna: es muy larga, pero demasiado estrecha.',
      { q: '¿Se ve la Gran Muralla a simple vista desde la Luna?', a: ['No, es demasiado estrecha', 'Sí, perfectamente', 'Solo de noche', 'Solo en invierno'], e: 'Es un mito muy extendido.' }),
    wpoi(1, 'seda', 'La Ruta de la Seda', 'Desde la dinastía Han, caravanas de camellos unían China con Persia, la India y el Mediterráneo. Por la Ruta de la Seda viajaban seda, papel, especias y caballos, pero también ideas, religiones y técnicas: así llegó el budismo a China.', 'Durante siglos, los chinos guardaron en secreto cómo se criaban los gusanos de seda. Revelarlo podía castigarse con la muerte.',
      { q: '¿Qué religión llegó a China por la Ruta de la Seda?', a: ['El budismo', 'El islam únicamente', 'El cristianismo protestante', 'El jainismo'], e: 'Procedente de la India a través de Asia central.' }),
    wpoi(2, 'inventos', 'Los cuatro grandes inventos', 'China dio al mundo cuatro grandes inventos: el papel, la brújula, la pólvora y la imprenta. El papel se perfeccionó hacia el año 105, y en el siglo once Bi Sheng inventó la imprenta de tipos móviles de arcilla, cuatro siglos antes que Gutenberg.', 'El libro impreso más antiguo con fecha conocida es un Sutra del Diamante chino del año 868.',
      { q: '¿Qué inventó Bi Sheng en el siglo XI?', a: ['La imprenta de tipos móviles', 'La brújula', 'El papel', 'El telescopio'], e: 'Con caracteres de arcilla cocida.' }),
    wpoi(3, 'examenes', 'Los exámenes imperiales', 'Durante más de mil años, China eligió a sus funcionarios mediante exámenes sobre los clásicos confucianos. En teoría, cualquier hombre podía aprobarlos y llegar a gobernar por su mérito, no por su familia. Los candidatos pasaban días encerrados en pequeñas celdas escribiendo.', 'Los exámenes imperiales se abolieron en 1905. Inspiraron los sistemas de oposiciones y servicio civil de Europa.',
      { q: '¿En qué se basaban los exámenes imperiales chinos?', a: ['En los clásicos confucianos', 'En la fuerza física', 'En la herencia familiar', 'En el sorteo'], e: 'Buscaban elegir funcionarios por mérito.' }),
    wpoi(4, 'jardinletrado', 'El jardín del letrado', 'Los sabios chinos construían jardines que imitaban la naturaleza en pequeño: rocas como montañas, estanques como lagos, pabellones para leer y escribir poemas. Pasear por ellos era una forma de meditación, en armonía con el Tao.', 'En los jardines chinos casi nunca hay líneas rectas: los caminos serpentean para que cada paso muestre una vista nueva.',
      { q: '¿Qué imitaban los jardines de los letrados chinos?', a: ['La naturaleza en pequeño: montañas y lagos', 'Los palacios europeos', 'Los campos de batalla', 'Los mercados'], e: 'Eran lugares para pensar y crear.' }),
  ],
  [ // XIV · India
    wpoi(0, 'indo', 'La civilización del Indo', 'Hace casi cinco mil años, en el valle del río Indo, florecieron ciudades como Mohenjo-Daro y Harappa, con calles rectas, casas de ladrillo, desagües cubiertos y grandes baños públicos. Tenían una escritura que todavía nadie ha logrado descifrar.', 'Mohenjo-Daro tenía un sistema de alcantarillado más avanzado que el de muchas ciudades europeas del siglo dieciocho.',
      { q: '¿Qué tenía de especial Mohenjo-Daro?', a: ['Calles planificadas y desagües cubiertos', 'Pirámides de oro', 'Una gran muralla', 'Rascacielos'], e: 'Su escritura sigue sin descifrar.' }),
    wpoi(1, 'nalanda', 'La universidad de Nalanda', 'Desde el siglo quinto, en Nalanda funcionó una de las primeras grandes universidades del mundo. Llegó a tener miles de estudiantes de Asia entera, que estudiaban filosofía budista, lógica, medicina, gramática y matemáticas. Su biblioteca tenía nueve pisos.', 'Fue destruida hacia 1193 por un ejército invasor. Se dice que su biblioteca ardió durante meses.',
      { q: '¿Qué era Nalanda?', a: ['Una gran universidad budista', 'Un templo hindú pequeño', 'Un puerto', 'Un palacio real'], e: 'Atraía estudiantes de China, Tíbet y Corea.' }),
    wpoi(2, 'cero', 'El cero y los números', 'Los números que usamos hoy, del cero al nueve, nacieron en la India. Los matemáticos indios usaron el cero como número, con sus propias reglas: el astrónomo Brahmagupta las escribió en el año 628. Los árabes los llevaron a Europa, por eso los llamamos números arábigos.', 'Antes del cero posicional, hacer multiplicaciones grandes con números romanos era muy difícil.',
      { q: '¿Dónde nació el cero como número?', a: ['En la India', 'En Roma', 'En Grecia', 'En Inglaterra'], e: 'Brahmagupta dio sus reglas en el año 628.' }),
    wpoi(3, 'ashoka', 'Los edictos de Ashoka', 'El emperador Ashoka, en el siglo tercero antes de Cristo, conquistó Kalinga en una batalla terrible. Horrorizado por la matanza, renunció a la guerra, se hizo budista y mandó grabar en rocas y columnas edictos sobre la compasión, la tolerancia religiosa y el cuidado de los animales.', 'El capitel de los leones de una de sus columnas es hoy el emblema nacional de la India.',
      { q: '¿Qué hizo Ashoka tras la batalla de Kalinga?', a: ['Renunció a la guerra y promovió la compasión', 'Conquistó China', 'Prohibió el budismo', 'Se retiró a Grecia'], e: 'Sus edictos son de los primeros textos de derechos y tolerancia.' }),
    wpoi(4, 'ganges', 'Benarés y el Ganges', 'A orillas del río Ganges, en Benarés, una de las ciudades habitadas más antiguas del mundo, miles de peregrinos bajan cada día las escalinatas, los ghats, para bañarse en el río sagrado. Muy cerca, en Sarnath, Buda dio su primer sermón.', 'Al atardecer, en los ghats se celebra el aarti: ofrendas de fuego y flores que flotan río abajo.',
      { q: '¿Qué ocurrió en Sarnath, cerca de Benarés?', a: ['Buda dio su primer sermón', 'Nació Mahavira', 'Se escribió el Tao Te Ching', 'Murió Ashoka'], e: 'Lo llaman la puesta en marcha de la rueda del Dharma.' }),
  ],
  [ // XV · África
    wpoi(0, 'guiza', 'Las pirámides de Guiza', 'Hace más de cuatro mil quinientos años, los egipcios levantaron en Guiza las pirámides de Keops, Kefrén y Micerinos, junto a la Gran Esfinge. La de Keops fue el edificio más alto del mundo durante casi cuatro mil años.', 'Hoy se sabe que no las construyeron esclavos, sino trabajadores organizados en equipos, que vivían en un poblado cercano y recibían pan y cerveza.',
      { q: '¿Quiénes construyeron las pirámides de Guiza, según los arqueólogos?', a: ['Trabajadores egipcios organizados en equipos', 'Extraterrestres', 'Esclavos romanos', 'Los incas'], e: 'Se han encontrado sus tumbas y su poblado.' }),
    wpoi(1, 'tombuctu', 'Tombuctú y sus manuscritos', 'En los siglos quince y dieciséis, Tombuctú, en el actual Mali, fue una gran ciudad de sabios, con mezquitas-universidades como la de Sankoré. Familias enteras guardaban bibliotecas de manuscritos de astronomía, medicina, derecho y filosofía. El sabio Ahmed Baba escribió decenas de obras.', 'En 2012, cuando unos extremistas ocuparon la ciudad, los habitantes sacaron en secreto cientos de miles de manuscritos para salvarlos.',
      { q: '¿Qué guardaban las familias de Tombuctú?', a: ['Bibliotecas de manuscritos científicos y filosóficos', 'Oro enterrado', 'Momias', 'Armas'], e: 'Muchos se salvaron gracias a su valentía.' }),
    wpoi(2, 'aksum', 'Las estelas de Aksum', 'En el norte de Etiopía floreció el reino de Aksum, que comerciaba con Roma, Arabia y la India y acuñaba sus propias monedas. Sus reyes levantaron enormes estelas de piedra, algunas de más de veinte metros, talladas como edificios de varios pisos.', 'Aksum fue uno de los primeros reinos del mundo en adoptar el cristianismo, en el siglo cuarto.',
      { q: '¿En qué actual país estaba el reino de Aksum?', a: ['Etiopía', 'Egipto', 'Sudáfrica', 'Marruecos'], e: 'Fue una gran potencia comercial de la Antigüedad.' }),
    wpoi(3, 'zimbabue', 'El Gran Zimbabue', 'Entre los siglos once y quince, en el sur de África, se levantó el Gran Zimbabue, una ciudad de muros de piedra de hasta once metros de altura, construidos sin argamasa. Era la capital de un reino que comerciaba oro y marfil hasta China.', 'Durante la época colonial, algunos se negaban a creer que lo hubieran construido africanos. Los arqueólogos demostraron que sí.',
      { q: '¿Cómo están construidos los muros del Gran Zimbabue?', a: ['Con piedras encajadas sin argamasa', 'Con cemento romano', 'Con ladrillos de barro', 'Con madera'], e: 'El país de Zimbabue tomó su nombre de esta ciudad.' }),
    wpoi(4, 'robben', 'La isla Robben', 'Frente a Ciudad del Cabo está la isla Robben, donde el régimen del apartheid encerró a presos políticos. Nelson Mandela pasó allí dieciocho de sus veintisiete años de prisión, rompiendo piedras en una cantera de cal. Los presos convirtieron la cárcel en una universidad clandestina.', 'Hoy la isla es un museo, y muchos de sus guías son antiguos presos políticos.',
      { q: '¿Quién pasó dieciocho años preso en la isla Robben?', a: ['Nelson Mandela', 'Desmond Tutu', 'Wangari Maathai', 'Kofi Annan'], e: 'Salió en libertad en 1990 y fue presidente en 1994.' }),
  ],
);

const sk = (r, r2, s, h, o = {}) => ({ robe: r, robe2: r2, skin: s, hair: h, beard: o.beard ?? false, hat: o.hat || 'none', acc: o.acc || 'none' });
NPCS.push(
  [ // X
    wnpc(0, 'pochteca', 'Ixtli', 'pochteca, comerciante', sk(0x6a4a2a, 0x2a8a8a, 0x9a6a46, 0x1a1410, { acc: 'staff' }), ['Viajo con mis cargadores hasta las tierras del cacao y las plumas de quetzal. Los pochtecas también somos espías del tlatoani: vemos y oímos mucho.', 'En el mercado de Tlatelolco hay jueces que revisan las medidas. Quien engaña con el peso es castigado. El comercio también necesita justicia.', 'En mis viajes he aprendido que cada pueblo tiene su lengua y sus dioses. Escuchar es la mejor mercancía.']),
    wnpc(1, 'partera', 'Citlali', 'partera, tícitl', sk(0xf4ecd8, 0x6a3a8a, 0x9a6a46, 0x1a1410, { hat: 'longhair' }), ['Ayudo a nacer a los niños. Cuando nace uno, le digo: has venido a la tierra donde se sufre y se goza. Así, desde el principio, sabe cómo es la vida.', 'Las mujeres que mueren al dar a luz son honradas como los guerreros: acompañan al Sol en su camino del cielo.', 'Conozco muchas hierbas que curan. Los españoles se asombran de nuestros médicos y jardines botánicos.'], true),
    wnpc(2, 'chinampera', 'Xóchitl', 'cultivadora de chinampas', sk(0xe8dcb8, 0x5a8a3a, 0x9a6a46, 0x1a1410, { hat: 'longhair' }), ['Cultivo maíz, frijol, calabaza y flores en mi chinampa. Las raíces de los ahuejotes sujetan la tierra al lago.', 'El maíz, el frijol y la calabaza son tres hermanos: crecen mejor juntos que separados. Como las personas.', 'Mi nombre significa flor. Las flores no son solo adorno: son canto, ofrenda y medicina.'], true),
  ],
  [ // XI
    wnpc(0, 'chasqui', 'Waman', 'chasqui, mensajero', sk(0xe8dcb8, 0xc84a2a, 0x9a6a46, 0x1a1410, { hat: 'cap' }), ['Corro por el Qhapaq Ñan con mi pututo, una caracola, para avisar al siguiente chasqui. Entre todos llevamos un mensaje de Quito a Cusco en pocos días.', 'También llevamos pescado fresco del mar al Inca, en Cusco, a más de tres mil metros de altura. ¡Llega todavía fresco!', 'Ningún chasqui corre solo: cada uno hace su tramo y pasa el mensaje. Así es el ayni.']),
    wnpc(1, 'quipucamayoc', 'Yupanqui', 'quipucamayoc, guardián de los quipus', sk(0xd8b048, 0x6a4a2a, 0x9a6a46, 0xd8d4cc, { acc: 'scroll' }), ['Leo y anudo los quipus. Este nudo largo es una unidad, estos nudos simples son decenas. El color dice si contamos llamas, papas o personas.', 'Con los quipus el Inca sabe cuánto hay en los depósitos y puede repartir en los años de sequía.', 'Los españoles no entendían cómo sin letras podíamos saber tanto. La memoria también se puede anudar.']),
    wnpc(2, 'aclla', 'Ocllo', 'tejedora de cumbi', sk(0xc84a2a, 0xd8b048, 0x9a6a46, 0x1a1410, { hat: 'longhair' }), ['Tejo cumbi, la tela más fina del imperio. Un manto puede llevar meses de trabajo. Los tejidos valían más que el oro para nosotros.', 'Los dibujos de los tejidos, los tocapus, quizá sean también una forma de escritura. Nadie los ha descifrado del todo.', 'Mi tejido une muchos hilos. Ninguno es fuerte solo, pero juntos sostienen el manto. Así es la comunidad.'], true),
  ],
  [ // XII
    wnpc(0, 'platero', 'Pedro Antilef', 'rütrafe, platero', sk(0x3a2a20, 0xd8d4cc, 0xb98563, 0x1a1410, { hat: 'cap' }), ['Trabajo la plata: trapelakucha, trarilonko, tupu. Las joyas que hago protegen a quien las lleva y cuentan de qué familia viene.', 'Cada forma tiene un sentido: el cielo, la tierra, los antepasados. Una joya mapuche también es una palabra.', 'Mi apellido, Antilef, significa sol veloz. Los nombres mapuche hablan de la naturaleza y del linaje.']),
    wnpc(1, 'palife', 'Kallfü', 'jugador de palín', sk(0x2a2a2a, 0x2a5aa8, 0xb98563, 0x1a1410, { acc: 'staff' }), ['Juego al palín con mi wiño, un palo curvo. Dos equipos llevan la pelota hasta el final de la cancha. Antes se jugaba para resolver conflictos entre comunidades.', 'Antes del partido, los jugadores se preparan, comparten comida y se hacen amigos. El rival no es un enemigo.', 'Mi nombre significa azul, como el cielo. Cuando juego siento el newen de mis antepasados.']),
    wnpc(2, 'witralwe', 'Rayen', 'tejedora de witral', sk(0x5a2a2a, 0xd8cfb8, 0xb98563, 0x1a1410, { hat: 'longhair' }), ['Tejo en el witral, el telar mapuche. Cada dibujo, cada ñimin, tiene un significado: el lukutuwe es una persona arrodillada, en actitud de respeto.', 'Mi abuela me enseñó a tejer conversando. Mientras el hilo pasa, pasa también la historia de la familia.', 'Mi nombre significa flor. Las mujeres mapuche guardamos la lengua y la memoria en los tejidos.'], true),
  ],
  [ // XIII
    wnpc(0, 'caligrafo', 'Wang', 'calígrafo', sk(0x2a3a5a, 0xe8e4dc, 0xd2a684, 0x1a1410, { acc: 'quill' }), ['Escribo con pincel y tinta. En la caligrafía, cada trazo muestra el carácter de quien escribe. Un trazo apresurado delata un corazón inquieto.', 'Los caracteres chinos no representan sonidos, sino ideas. Por eso personas que hablan lenguas distintas pueden leer el mismo texto.', 'Para preparar la tinta, froto la barra en la piedra despacio. Así preparo también mi mente.']),
    wnpc(1, 'sedera', 'Mei', 'criadora de gusanos de seda', sk(0xc84a5a, 0xf2efe6, 0xe0b896, 0x1a1410, { hat: 'longhair' }), ['Crío gusanos de seda con hojas de morera. Cada capullo es un solo hilo que puede medir casi un kilómetro.', 'Según la leyenda, la emperatriz Leizu descubrió la seda cuando un capullo cayó en su taza de té y se deshizo en hilo.', 'Nuestra seda viaja hasta Roma. Allí la pagan a precio de oro sin saber de dónde viene.'], true),
    wnpc(2, 'arrocero', 'Li', 'campesino de arrozales', sk(0xd8cfb8, 0x5a8a3a, 0xd2a684, 0x2a2018, { hat: 'cap' }), ['Cultivo arroz en terrazas inundadas. Hace falta que toda la aldea se ponga de acuerdo para repartir el agua.', 'El maestro Kong dice que el buen gobernante es como el viento y el pueblo como la hierba: la hierba se inclina hacia donde sopla el viento.', 'El viejo Laozi diría que el agua no lucha, pero llena cada terraza. Yo aprendo de ella todos los días.']),
  ],
  [ // XIV
    wnpc(0, 'monje', 'Ananda', 'monje budista', sk(0xc8641a, 0xf0a040, 0xc49372, 0x1a1410, { hat: 'bald' }), ['Cada mañana salgo con mi cuenco a recibir comida. No pido: acepto lo que me dan. Así practicamos el desapego.', 'Meditar es observar la respiración y los pensamientos sin agarrarlos, como nubes que pasan.', 'El maestro decía que el odio no se apaga con odio, sino con amor. Es una ley eterna.']),
    wnpc(1, 'alfarera', 'Lakshmi', 'alfarera', sk(0xf0a040, 0xc84a5a, 0xa8754f, 0x1a1410, { hat: 'longhair' }), ['Hago cuencos y lámparas de barro, las diyas, que encendemos en la fiesta de las luces, Diwali.', 'El barro me enseña que todo cambia de forma: tierra, cuenco, polvo otra vez. Nada es para siempre.', 'Un cuenco es útil por su vacío. Eso dicen también los sabios: el vacío no es nada, es espacio para la vida.'], true),
    wnpc(2, 'matematico', 'Aryan', 'estudiante de matemáticas', sk(0xf4f0e8, 0x2a5aa8, 0xa8754f, 0x1a1410, { acc: 'book' }), ['Estudio con los astrónomos. Usamos nueve cifras y un círculo vacío, el cero, que llamamos shunya, el vacío.', 'Con el cero, un número cambia de valor según su posición. Es como si el vacío ordenara el mundo.', 'Aryabhata calculó que la Tierra gira sobre sí misma, en el siglo quinto. Muchos no le creyeron.']),
  ],
  [ // XV
    wnpc(0, 'griot', 'Mamadou', 'griot, guardián de la memoria', sk(0xf2efe6, 0xc84a2a, 0x5a3a28, 0x1a1410, { acc: 'staff' }), ['Soy griot: guardo la historia de los pueblos en mi memoria y la canto con la kora. Cuando un anciano muere, decimos, es una biblioteca que arde.', 'Canto la epopeya de Sundiata Keita, que fundó el imperio de Mali. Se transmite de padres a hijos desde hace ochocientos años.', 'Mansa Musa, rey de Mali, peregrinó a La Meca con tanto oro que bajó su precio en El Cairo durante años.']),
    wnpc(1, 'escriba', 'Ahmed', 'copista de Tombuctú', sk(0xe8e4dc, 0x2a6a4a, 0x5a3a28, 0x1a1410, { acc: 'book' }), ['Copio manuscritos de astronomía, medicina y derecho. En Tombuctú, la sal viene del norte, el oro del sur y la sabiduría de los libros.', 'El sabio Ahmed Baba escribió decenas de libros y defendió que nadie debía ser esclavizado por su color de piel.', 'Cuidamos los manuscritos de la humedad y de las termitas como se cuida a un recién nacido.']),
    wnpc(2, 'plantadora', 'Njeri', 'plantadora del Cinturón Verde', sk(0xf0a040, 0x2a6a3a, 0x5a3a28, 0x1a1410, { hat: 'longhair' }), ['Con otras mujeres de mi aldea plantamos árboles. Ahora tenemos leña, fruta y sombra, y el agua del río vuelve a estar limpia.', 'La señora Maathai nos enseñó que no hace falta un título para cuidar la tierra. Basta con unas manos y una semilla.', 'En mi lengua, el kikuyu, decimos que la tierra no es nuestra: la hemos recibido prestada de nuestros hijos.'], true),
  ],
);

Object.assign(QUESTS, {
  tochihuitzin: { text: 'Para saber si la vida es sueño, mira lo que perdura. Visita el Templo Mayor y escucha a Xóchitl en su chinampa. Luego dime qué dejé dicho.', needs: { pois: ['templomayor'], npcs: ['chinampera'] },
    riddle: { q: '¿Qué afirma el canto de Tochihuitzin?', a: ['Que venimos solo a soñar', 'Que la tierra es eterna', 'Que el oro es lo único verdadero', 'Que no hay que cantar'] } },
  macuilxochitzin: { text: 'Visita las escuelas de mi pueblo y escucha a Citlali, la partera. Ella sabe que las mujeres también hacemos la historia. Luego dime a quién da protagonismo mi canto.', needs: { pois: ['calmecac'], npcs: ['partera'] },
    riddle: { q: '¿A quiénes da protagonismo el canto de Macuilxochitzin?', a: ['A mujeres que intercedieron por un guerrero herido', 'A los dioses del cielo', 'A los comerciantes', 'A los españoles'] } },
  tecayehuatzin: { text: 'Visita el gran mercado de Tlatelolco y escucha a Ixtli, el comerciante, que ha conocido muchos pueblos. Luego dime: según mi diálogo, ¿qué hace la flor y el canto?', needs: { pois: ['tlatelolco'], npcs: ['pochteca'] },
    riddle: { q: 'Según Tecayehuatzin, ¿qué hace la flor y el canto?', a: ['Reúne a los amigos', 'Gana las guerras', 'Hace ricos a los nobles', 'Engaña a los dioses'] } },
  incaroca: { text: 'Antes de debatir, aprende como en las yachaywasi. Visita los quipus y escucha a Yupanqui, el quipucamayoc. Luego dime qué sistema numérico usaban los quipus.', needs: { pois: ['quipus'], npcs: ['quipucamayoc'] },
    riddle: { q: '¿Qué sistema numérico usaban los quipus?', a: ['Decimal', 'Binario', 'Romano', 'Ninguno: solo eran adornos'] } },
  garcilaso: { text: 'Visita Cusco, mi ciudad natal, y escucha a Ocllo, la tejedora, que une hilos como yo uní dos mundos. Luego dime cómo me llamé a mí mismo con orgullo.', needs: { pois: ['cusco'], npcs: ['aclla'] },
    riddle: { q: '¿Cómo se llamaba a sí mismo con orgullo el Inca Garcilaso?', a: ['Mestizo', 'Conquistador', 'Extranjero', 'Rey de España'] } },
  guamanpoma: { text: 'Recorre el Qhapaq Ñan y escucha a Waman, el chasqui. Así conocerás el reino como yo lo conocí caminando. Luego dime cómo describí el mundo tras la conquista.', needs: { pois: ['qhapaqnan'], npcs: ['chasqui'] },
    riddle: { q: '¿Cómo describió Guamán Poma el mundo tras la conquista?', a: ['Como un mundo al revés', 'Como el mejor de los mundos', 'Como un sueño feliz', 'Como una edad de oro'] } },
  machi: { text: 'Visita el rewe y escucha a Rayen, la tejedora, que guarda la memoria en sus hilos. Luego dime qué es para nosotros la enfermedad.', needs: { pois: ['rewe'], npcs: ['witralwe'] },
    riddle: { q: 'Para la medicina mapuche, ¿qué es la enfermedad?', a: ['Un desequilibrio entre la persona, la comunidad y la naturaleza', 'Un castigo sin remedio', 'Un problema solo del cuerpo', 'Algo que no tiene causa'] } },
  kimche: { text: 'Visita las araucarias y la ruka, y escucha a Kallfü, el jugador de palín. Luego dime qué significa mapuche.', needs: { pois: ['pewen', 'ruka'], npcs: ['palife'] },
    riddle: { q: '¿Qué significa la palabra mapuche?', a: ['Gente de la tierra', 'Guerreros del sur', 'Hijos del mar', 'Pueblo del sol'] } },
  janequeo: { text: 'Visita el lugar del Parlamento de Quilín y escucha a Pedro, el platero. Luego dime qué río fue frontera de nuestra tierra.', needs: { pois: ['quilin'], npcs: ['platero'] },
    riddle: { q: '¿Qué río fue reconocido como frontera del territorio mapuche en 1641?', a: ['El Biobío', 'El Maule', 'El Amazonas', 'El Paraná'] } },
  laozi: { text: 'Visita el jardín del letrado y escucha a Li, el campesino de los arrozales, que conoce bien el agua. Luego dime qué significa wu wei.', needs: { pois: ['jardinletrado'], npcs: ['arrocero'] },
    riddle: { q: '¿Qué significa wu wei?', a: ['Actuar sin forzar, como el agua', 'Luchar siempre', 'Obedecer al emperador', 'No hacer nunca nada'] } },
  banzhao: { text: 'Visita los cuatro grandes inventos y escucha a Wang, el calígrafo. Luego dime qué defendí para las niñas.', needs: { pois: ['inventos'], npcs: ['caligrafo'] },
    riddle: { q: '¿Qué defendió Ban Zhao para las niñas?', a: ['Que fueran educadas como los niños', 'Que no aprendieran a leer', 'Que gobernaran el imperio', 'Que dejaran la familia'] } },
  zhuangzi: { text: 'Recorre la Ruta de la Seda y escucha a Mei, que cría gusanos que se transforman en mariposas. Luego dime qué soñé yo.', needs: { pois: ['seda'], npcs: ['sedera'] },
    riddle: { q: '¿Qué soñó Zhuangzi?', a: ['Que era una mariposa', 'Que era emperador', 'Que era un dragón', 'Que volaba a la Luna'] } },
  gargi: { text: 'Visita la universidad de Nalanda y escucha a Aryan, el estudiante de matemáticas. Luego dime qué es Brahman.', needs: { pois: ['nalanda'], npcs: ['matematico'] },
    riddle: { q: '¿Qué es Brahman en las Upanishads?', a: ['La realidad última que sostiene todo', 'Un rey', 'Un río', 'Un dios menor de la lluvia'] } },
  mahavira: { text: 'Visita los edictos de Ashoka y escucha a Lakshmi, la alfarera. Luego dime qué significa ahimsa.', needs: { pois: ['ashoka'], npcs: ['alfarera'] },
    riddle: { q: '¿Qué significa ahimsa?', a: ['No dañar a ningún ser vivo', 'Meditar en silencio', 'Ayunar', 'Viajar a pie'] } },
  nagarjuna: { text: 'Visita el lugar donde nació el cero y escucha a Ananda, el monje. Luego dime qué es la vacuidad.', needs: { pois: ['cero'], npcs: ['monje'] },
    riddle: { q: 'Para Nagarjuna, ¿qué significa que todo está vacío?', a: ['Que nada existe por sí solo: todo depende de otras cosas', 'Que nada existe en absoluto', 'Que el mundo es un sueño de Dios', 'Que hay que vaciar los templos'] } },
  ptahhotep: { text: 'Visita las pirámides de Guiza y escucha a Mamadou, el griot. Luego dime dónde está escondida la buena palabra.', needs: { pois: ['guiza'], npcs: ['griot'] },
    riddle: { q: 'Según Ptahhotep, ¿dónde puede encontrarse la buena palabra?', a: ['Incluso entre las sirvientas que muelen el grano', 'Solo en el palacio del faraón', 'Solo en los templos', 'En ningún lugar'] } },
  zerayacob: { text: 'Visita Tombuctú y escucha a Ahmed, el copista. Él sabe lo que vale un libro. Luego dime qué guía propuse para distinguir lo verdadero.', needs: { pois: ['tombuctu'], npcs: ['escriba'] },
    riddle: { q: '¿Qué guía propone Zera Yacob para distinguir lo verdadero?', a: ['La luz de la razón que todos tenemos', 'La autoridad de los sacerdotes', 'La costumbre', 'El oráculo'] } },
  maathai: { text: 'Visita el Gran Zimbabue y escucha a Njeri, la plantadora. Luego dime qué hizo el colibrí ante el incendio.', needs: { pois: ['zimbabue'], npcs: ['plantadora'] },
    riddle: { q: 'En la historia de Wangari Maathai, ¿qué hace el colibrí ante el incendio?', a: ['Lleva gotas de agua: hace lo mejor que puede', 'Huye como los demás', 'Se esconde', 'Pide ayuda al león'] } },
});

Object.assign(ANECDOTES, {
  tochihuitzin: ['Mis cantos se cantaban en las fiestas con tambores de madera, el huéhuetl y el teponaztli. La poesía náhuatl no se leía: se cantaba y se bailaba.', 'Se cuenta que, siendo joven, los señores me pidieron un canto para una fiesta, y yo les canté que todo es sueño. Algunos se rieron; otros se quedaron pensando.'],
  macuilxochitzin: ['Mi padre, Tlacaélel, fue el hombre más poderoso de Tenochtitlan después del tlatoani. Yo crecí escuchando consejos de gobierno, pero elegí el canto.', 'En mi canto cuento que una mujer otomí ofreció comida al tlatoani Axayácatl para que perdonara a un capitán. En medio de la guerra, una ofrenda de paz.'],
  tecayehuatzin: ['Mi ciudad, Huexotzinco, fue enemiga de Tenochtitlan en las guerras floridas, pero a mi palacio venían poetas de todas partes. La poesía cruzaba las fronteras.', 'Uno de los poetas de mi diálogo, Ayocuan, dijo que los cantos son como plumas de quetzal: preciosos, pero se deshacen.'],
  tlacaelel: ['Tres veces me ofrecieron ser tlatoani, y tres veces lo rechacé. Preferí gobernar desde la sombra, como consejero.', 'Cuando los tepanecas de Azcapotzalco nos sometían, fui yo quien se atrevió a llevarles el mensaje de guerra. Muchos pensaron que no volvería con vida.'],
  incaroca: ['Garcilaso cuenta que dije que los hijos de la gente común no debían aprender las ciencias de los nobles. Hoy sabemos que el saber debe ser de todos.', 'Mandé canalizar el agua de los ríos que bajaban a Cusco. Se dice que el agua de Hurin Cusco, la parte baja, llegó gracias a mí.'],
  garcilaso: ['De niño vi en Cusco las momias de los incas, sentadas, con las manos cruzadas, tan bien conservadas que parecían vivas. Toqué un dedo de Huayna Cápac: era duro como la madera.', 'Firmé siempre como Inca Garcilaso de la Vega, uniendo mis dos linajes. En España muchos se sorprendían de que un indio escribiera tan bien.'],
  guamanpoma: ['Viajé ya anciano hasta Lima, a pie, con mi hijo y mi caballo, para entregar mi manuscrito al virrey y que lo enviara al rey. Escribí que estaba pobre y desnudo, pero que había cumplido.', 'En mis dibujos aparezco yo mismo, arrodillado ante el rey Felipe III, entregándole mi libro. Era mi manera de decir: aquí estoy, escúchame.'],
  pachacutec: ['Cuando los chancas atacaron Cusco, la leyenda dice que las piedras del campo se convirtieron en guerreros para ayudarme. Se llamaron los pururaucas.', 'Mandé que se hicieran estatuas de oro de los incas anteriores y que se guardaran sus historias en quipus y cantos, para que la memoria del imperio no se perdiera.'],
  machi: ['Muchas machis reciben su llamado en un sueño, o tras una enfermedad que nadie puede curar. Al aceptar su camino, sanan.', 'En la ceremonia del machitun, la machi toca el kultrún y entra en trance para conocer el origen de la enfermedad y pedir la curación.'],
  kimche: ['Cuando se encuentran dos mapuches que no se conocen, hacen el pentukun: un saludo largo en el que se preguntan por la salud de la familia, del territorio y de los animales.', 'Decimos que el weichafe, el guerrero, debe ser primero un buen conversador: la palabra es el primer camino para resolver un conflicto.'],
  janequeo: ['Los cronistas españoles se asombraron de que los guerreros obedecieran a una mujer. Uno escribió que era más temida que muchos capitanes.', 'Se cuenta que, tras atacar un fuerte español, me retiré a las montañas, donde los soldados nunca pudieron alcanzarme.'],
  lautaro: ['Cuando volví con mi pueblo, enseñé a los mapuche que los caballos se cansan y los soldados con armadura también. Atacábamos en grupos que se iban relevando.', 'Antes de la batalla de Tucapel envié a un grupo pequeño para provocar a los españoles y atraerlos a una trampa. Valdivia cayó en ella.'],
  laozi: ['Se cuenta que Confucio fue a visitarme. Al volver dijo a sus discípulos: sé cómo vuela el pájaro, cómo nada el pez y cómo corre la fiera. Pero el dragón, que sube al cielo en las nubes, no sé cómo es. Hoy he visto a Laozi: es como un dragón.', 'Una leyenda dice que nací ya anciano, con el pelo blanco, después de que mi madre me llevara en su vientre más de sesenta años.'],
  banzhao: ['A los setenta años todavía enseñaba en la biblioteca del palacio. Los eruditos venían a pedirme que les explicara pasajes difíciles del Libro de Han.', 'Escribí un poema sobre un viaje con mi hijo al este, en el que le aconsejaba ser honesto y humilde en su cargo.'],
  zhuangzi: ['Un día me encontré una calavera en el camino y la usé de almohada. En sueños me habló y me dijo que estar muerto era más tranquilo que ser rey. Yo no sé si creerle.', 'Mi amigo Huizi era mi gran rival en los debates. Cuando murió, dije que ya no tenía con quién hablar.'],
  confucio: ['Un día, pasando junto a una montaña, encontré a una mujer llorando: un tigre había matado a su suegro, a su marido y a su hijo. Le pregunté por qué no se iba de allí. Respondió: aquí no hay un gobierno cruel. Dije a mis discípulos: un mal gobierno es más temible que un tigre.', 'Cuando escuché por primera vez la música de Shao, quedé tan conmovido que durante tres meses no noté el sabor de la carne.'],
  gargi: ['Según los textos, era la única mujer en el gran debate del rey Janaka, sentada entre los sabios más famosos de la India.', 'Antes de mi última pregunta dije a la asamblea: le haré dos preguntas a Yajnavalkya, y si las responde, nadie lo vencerá. Lo comparé con un guerrero que tensa dos flechas.'],
  mahavira: ['Se cuenta que, meditando, unos pastores me clavaron astillas en los oídos porque no les respondía. Ni siquiera entonces respondí con violencia.', 'Durante doce años de silencio caminé desnudo por los bosques, sin casa ni posesiones. Los jainistas digambara siguen hoy ese ejemplo.'],
  nagarjuna: ['Una leyenda cuenta que los nagas, seres serpiente que viven bajo las aguas, guardaban textos budistas escondidos, y que me los entregaron. Por eso me llaman Nagarjuna.', 'Escribí una carta a un rey amigo, la Guirnalda preciosa, aconsejándole gobernar con compasión, cuidar a los pobres y construir hospitales.'],
  buda: ['Un día un hombre me insultó a gritos. Le pregunté: si alguien te ofrece un regalo y tú no lo aceptas, ¿de quién es el regalo? Respondió: del que lo ofrece. Entonces, le dije, tu insulto sigue siendo tuyo.', 'Una madre, Kisa Gotami, vino con su hijo muerto en brazos pidiendo una medicina. Le pedí un grano de mostaza de una casa donde no hubiera muerto nadie. No encontró ninguna. Así comprendió que la muerte es parte de la vida.'],
  ptahhotep: ['Pedí al faraón que me dejara un bastón de vejez, es decir, un hijo al que enseñar. Él aceptó, y así nacieron mis enseñanzas.', 'Al final de mis consejos escribí que había llegado a los ciento diez años, la edad perfecta para un sabio egipcio.'],
  zerayacob: ['En la cueva comía lo que me traían los campesinos de los alrededores y cuidaba de no ser visto. Allí escribí que había encontrado más verdad que en los libros de los doctores.', 'Cuando salí de la cueva, trabajé como escriba para un hombre rico, Habtu, y enseñé a sus hijos. Uno de ellos, Walda Heywat, se convirtió también en filósofo.'],
  maathai: ['Cuando defendí el parque Uhuru, el presidente me llamó una mujer loca. Le respondí que si así eran las mujeres locas, ojalá hubiera muchas más.', 'Al recibir el Nobel, planté un árbol en mi tierra con mis propias manos. Fue mi manera de celebrar.'],
  tutu: ['Bailaba en público cuando estaba contento, aunque fuera arzobispo. Decía que Dios tiene sentido del humor.', 'De niño, vi a un sacerdote blanco, Trevor Huddleston, quitarse el sombrero para saludar a mi madre, una mujer negra. En el apartheid nadie hacía eso. Nunca lo olvidé.'],
});

BOOKS.push(
  [ { id: 'cantares', author: 'tecayehuatzin', by: 'Poetas nahuas', title: 'Cantares mexicanos', year: 'siglo XVI', kind: 'antología de poesía', at: B2[0],
    parts: [
      { t: 'Una biblioteca de cantos', x: 'Los Cantares mexicanos son una recopilación de unos noventa poemas en náhuatl, escritos con letras latinas en el siglo dieciséis por estudiantes nahuas. Se conservan en la Biblioteca Nacional de México. Son una de las grandes fuentes de la filosofía náhuatl.' },
      { t: 'Flor y canto', x: 'Muchos cantos se preguntan si la poesía puede decir algo verdadero. Los poetas la llaman in xóchitl in cuícatl, flor y canto: algo bello y frágil que viene del cielo y nos acerca al Dador de la vida.' },
      { t: 'Todo pasa', x: 'Una pregunta se repite: ¿acaso de veras se vive en la tierra? No para siempre aquí: solo un poco. Aunque sea jade se quiebra, aunque sea oro se rompe. La fragilidad de la vida es el gran tema de estos poemas.' },
      { t: 'El diálogo de Huexotzinco', x: 'Uno de los cantos recoge el diálogo que organizó Tecayehuatzin. Varios poetas dan su opinión sobre qué es la poesía. La conclusión: la flor y el canto es lo que reúne a los amigos en la tierra.' },
    ],
    quote: '¿Acaso de veras se vive en la tierra? No para siempre aquí: solo un poco.',
    q: { q: '¿Cómo se llama la poesía en náhuatl, según los Cantares mexicanos?', a: ['In xóchitl in cuícatl: flor y canto', 'Ometéotl', 'Tlamatini', 'Calmécac'], e: 'Algo bello y frágil que nos acerca a lo verdadero.' } } ],
  [ { id: 'comentarios', author: 'garcilaso', by: 'Inca Garcilaso de la Vega', title: 'Comentarios Reales de los Incas', year: '1609', kind: 'historia', at: B2[0],
    parts: [
      { t: 'Un mestizo que escribe', x: 'El Inca Garcilaso publicó en Lisboa en 1609 la primera parte de los Comentarios Reales. Quiso contar la historia de los incas desde dentro, como hijo de una princesa inca, para corregir los errores de los cronistas españoles.' },
      { t: 'El origen de los incas', x: 'Garcilaso cuenta el mito de Manco Cápac y Mama Ocllo, hijos del Sol, que salieron del lago Titicaca con una vara de oro. Donde la vara se hundiera en la tierra, fundarían su ciudad. Así nació Cusco.' },
      { t: 'Leyes y costumbres', x: 'El libro describe el gobierno de los incas: los depósitos de alimentos, los caminos, los quipus, la educación de los amautas, el culto al Sol y la reciprocidad entre comunidades. Garcilaso compara a Cusco con Roma.' },
      { t: 'Dos mundos', x: 'Garcilaso se presenta como mestizo con orgullo. Su libro inspiró siglos después a los independentistas, y la Corona española llegó a prohibir su lectura tras la rebelión de Túpac Amaru II en 1780.' },
    ],
    quote: 'Me llamo mestizo a boca llena y me honro con él.',
    q: { q: '¿Desde dónde salieron Manco Cápac y Mama Ocllo, según los Comentarios Reales?', a: ['Del lago Titicaca', 'Del océano Pacífico', 'De la selva amazónica', 'De Tenochtitlan'], e: 'Fundaron Cusco donde se hundió su vara de oro.' } } ],
  [],
  [ { id: 'taoteching', author: 'laozi', by: 'Laozi', title: 'Tao Te Ching', year: 'siglos VI – IV a.C.', kind: 'poema filosófico', at: B2[0],
      parts: [
        { t: 'El libro del camino', x: 'El Tao Te Ching es un breve libro de ochenta y un capítulos en verso. Es uno de los libros más traducidos del mundo. Habla del Tao, el camino de todas las cosas, y del Te, la virtud o fuerza de quien lo sigue.' },
        { t: 'Lo que no se puede nombrar', x: 'El Tao que puede nombrarse no es el Tao eterno. El nombre que puede pronunciarse no es el nombre eterno. Antes del cielo y la tierra ya existía algo sin forma, silencioso y vacío: lo llamo Tao.' },
        { t: 'El agua y el vacío', x: 'Lo más blando del mundo vence a lo más duro, como el agua. Treinta radios se unen en un cubo, y es su vacío lo que hace útil la rueda. Lo que hay de ser sirve, pero lo que no hay es lo que lo hace útil.' },
        { t: 'Gobernar sin forzar', x: 'El mejor gobernante es aquel de quien el pueblo apenas sabe que existe. Cuando termina su obra, el pueblo dice: lo hicimos nosotros. Gobernar un gran país es como cocinar un pez pequeño: no hay que removerlo demasiado.' },
      ],
      quote: 'Gobernar un gran país es como cocinar un pez pequeño.',
      q: { q: 'Según el Tao Te Ching, ¿qué hace útil a una rueda o a un cuenco?', a: ['Su vacío', 'Su color', 'Su precio', 'Su tamaño'], e: 'Lo que no hay es lo que lo hace útil.' } },
    { id: 'analectas', author: 'confucio', by: 'Discípulos de Confucio', title: 'Analectas', year: 'siglos V – III a.C.', kind: 'diálogos', at: B2[1],
      parts: [
        { t: 'Palabras del maestro', x: 'Las Analectas recogen frases y conversaciones de Confucio con sus discípulos. Empiezan así: aprender y practicar a su tiempo lo aprendido, ¿no es un placer? Recibir a un amigo que viene de lejos, ¿no es una alegría?' },
        { t: 'Una vida de estudio', x: 'Confucio resume su vida: a los quince años me dediqué al estudio; a los treinta me mantuve firme; a los cuarenta no tuve dudas; a los cincuenta conocí el mandato del cielo; a los sesenta mi oído se volvió dócil; a los setenta seguía mi corazón sin salirme de lo justo.' },
        { t: 'La reciprocidad', x: 'Un discípulo pregunta si hay una palabra que pueda guiar toda la vida. Confucio responde: reciprocidad. Lo que no deseas para ti, no lo hagas a los demás.' },
        { t: 'Saber que no se sabe', x: 'Confucio enseña a su discípulo Zilu: cuando sabes algo, reconoce que lo sabes; cuando no sabes algo, reconoce que no lo sabes. Eso es saber. Una idea muy parecida a la de Sócrates, que vivió poco después.' },
      ],
      quote: 'Cuando sabes algo, reconoce que lo sabes; cuando no lo sabes, reconoce que no lo sabes. Eso es saber.',
      q: { q: 'Según las Analectas, ¿qué palabra puede guiar toda la vida?', a: ['Reciprocidad', 'Poder', 'Riqueza', 'Silencio'], e: 'Lo que no deseas para ti, no lo hagas a los demás.' } } ],
  [ { id: 'dhammapada', author: 'buda', by: 'Tradición budista', title: 'Dhammapada', year: 'siglo III a.C.', kind: 'versos', at: B2[0],
    parts: [
      { t: 'El camino de la enseñanza', x: 'El Dhammapada, el camino del dharma, reúne cuatrocientos veintitrés versos atribuidos a Buda. Es uno de los textos budistas más leídos. Sus versos son breves y fáciles de memorizar, como proverbios.' },
      { t: 'La mente', x: 'Empieza así: la mente precede a todas las cosas; todo está hecho por la mente. Si uno habla o actúa con una mente impura, el sufrimiento lo sigue como la rueda sigue la pata del buey que tira del carro.' },
      { t: 'El odio y el amor', x: 'El odio nunca se apaga con odio; solo con la ausencia de odio se apaga. Esta es una ley eterna. Es mejor vencerse a uno mismo que vencer a mil hombres mil veces en la batalla.' },
      { t: 'Sé tu propia lámpara', x: 'Nadie nos salva más que nosotros mismos. Los budas solo señalan el camino; cada uno debe recorrerlo. Vive con atención: la atención es el camino a lo que no muere; la falta de atención, el camino de la muerte.' },
    ],
    quote: 'El odio nunca se apaga con odio; solo con la ausencia de odio se apaga.',
    q: { q: 'Según el Dhammapada, ¿con qué se apaga el odio?', a: ['Con la ausencia de odio', 'Con más odio', 'Con la venganza', 'Con el olvido'], e: 'Es una ley eterna.' } } ],
  [ { id: 'hatata', author: 'zerayacob', by: 'Zera Yacob', title: 'Hatata', year: '1667', kind: 'tratado', at: B2[0],
    parts: [
      { t: 'Una investigación', x: 'Hatata significa investigación en ge’ez, la lengua clásica de Etiopía. Zera Yacob la escribió en 1667, ya anciano, para contar cómo había llegado a sus ideas usando solo la razón.' },
      { t: 'La cueva', x: 'Perseguido por las disputas religiosas, Zera Yacob se escondió dos años en una cueva. Allí se preguntó por qué cristianos, musulmanes y judíos se acusaban mutuamente de mentir. Si todos decían tener la verdad, había que examinarla.' },
      { t: 'La luz de la razón', x: 'Su conclusión: Dios ha dado a todos los seres humanos la luz de la razón. Lo que contradice la razón y la bondad no puede venir de Dios. Así critica las costumbres que discriminan a las mujeres o justifican la esclavitud.' },
      { t: 'Igualdad y armonía', x: 'Zera Yacob defiende que todas las personas son iguales, que el matrimonio debe ser entre iguales y que hay que vivir con moderación y gratitud. Algunos estudiosos dudaron de su autoría, pero hoy la mayoría la reconoce como una obra etíope auténtica.' },
    ],
    quote: 'Todos los seres humanos son iguales ante Dios, y todos son inteligentes, porque todos son sus criaturas.',
    q: { q: '¿Qué significa «Hatata»?', a: ['Investigación', 'Oración', 'Historia del rey', 'Canto de guerra'], e: 'En ge’ez, la lengua clásica etíope.' } } ],
);
BOOKS.slice(CAMPAIGN).forEach((list) => list.forEach((b) => { b.q.book = b.title; }));
